7	import { selectModelForAvailability } from '../../availability/policyHelpers.js';
8	import type { Config } from '../../config/config.js';
9	import { resolveModel } from '../../config/models.js';
10	import type { BaseLlmClient } from '../../core/baseLlmClient.js';
11	import type {
12	  RoutingContext,
13	  RoutingDecision,
14	  RoutingStrategy,
15	} from '../routingStrategy.js';
16	
17	export class FallbackStrategy implements RoutingStrategy {
18	  readonly name = 'fallback';
19	
20	  async route(
21	    context: RoutingContext,
22	    config: Config,
23	    _baseLlmClient: BaseLlmClient,
24	  ): Promise<RoutingDecision | null> {
25	    const requestedModel = context.requestedModel ?? config.getModel();
26	    const resolvedModel = resolveModel(
27	      requestedModel,
28	      config.getGemini31LaunchedSync?.() ?? false,
29	    );
30	    const service = config.getModelAvailabilityService();
31	    const snapshot = service.snapshot(resolvedModel);
32	
33	    if (snapshot.available) {
34	      return null;
35	    }
36	
37	    const selection = selectModelForAvailability(config, requestedModel);
38	
39	    if (
40	      selection?.selectedModel &&
41	      selection.selectedModel !== requestedModel
42	    ) {
43	      return {
44	        model: selection.selectedModel,
45	        metadata: {
46	          source: this.name,
47	          latencyMs: 0,
48	          reasoning: `Model ${requestedModel} is unavailable (${snapshot.reason}). Using fallback: ${selection.selectedModel}`,
49	        },
50	      };
51	    }
52	
53	    return null;
54	  }
55	}
