import type { Config } from '../../config/config.js';
import {
  DEFAULT_GEMINI_FLASH_MODEL,
  DEFAULT_GEMINI_MODEL,
  DEFAULT_GEMINI_MODEL_AUTO,
  PREVIEW_GEMINI_FLASH_MODEL,
  PREVIEW_GEMINI_MODEL,
  isAutoModel,
} from '../../config/models.js';
import { ApprovalMode } from '../../policy/types.js';
import type { BaseLlmClient } from '../../core/baseLlmClient.js';
import type {
  RoutingContext,
  RoutingDecision,
  RoutingStrategy,
} from '../routingStrategy.js';

/**
 * Routes based on the current phase of the planning workflow.
 *
 * When automatic model selection is active, this strategy selects a
 * high-reasoning (Pro) model while the user is planning (ApprovalMode.PLAN)
 * and a faster (Flash) model once a plan has been approved and execution
 * begins.
 */
export class ApprovalModeStrategy implements RoutingStrategy {
  readonly name = 'approval-mode';

  async route(
    context: RoutingContext,
    config: Config,
    _baseLlmClient: BaseLlmClient,
  ): Promise<RoutingDecision | null> {
    const startTime = Date.now();

    const autoModel = context.requestedModel ?? config.getModel();

    // This strategy only applies to automatic model selection.
    if (!isAutoModel(autoModel)) {
      return null;
    }

    // Respect the user's configuration for plan-mode routing.
    if (!config.getPlanModeRoutingEnabled()) {
      return null;
    }

    const approvalMode = config.getApprovalMode();
    const approvedPlanPath = config.getApprovedPlanPath();

    // If we are neither planning nor executing an approved plan, defer to the
    // next strategy.
    if (approvalMode !== ApprovalMode.PLAN && !approvedPlanPath) {
      return null;
    }

    const isDefaultFamily = autoModel === DEFAULT_GEMINI_MODEL_AUTO;

    // During planning, route to the high-reasoning Pro model.
    if (approvalMode === ApprovalMode.PLAN) {
      return {
        model: isDefaultFamily ? DEFAULT_GEMINI_MODEL : PREVIEW_GEMINI_MODEL,
        metadata: {
          source: this.name,
          latencyMs: Date.now() - startTime,
          reasoning: 'Routing to Pro model because ApprovalMode is PLAN.',
        },
      };
    }

    // During execution of an approved plan, route to the faster Flash model.
    return {
      model: isDefaultFamily
        ? DEFAULT_GEMINI_FLASH_MODEL
        : PREVIEW_GEMINI_FLASH_MODEL,
      metadata: {
        source: this.name,
        latencyMs: Date.now() - startTime,
        reasoning: `Routing to Flash model because an approved plan exists at ${approvedPlanPath}.`,
      },
    };
  }
}
